:root{
  --fire:#e85d04;
  --ember:#dc2f02;
  --gold:#f48c06;
  --smoke:#1a1008;
  --ash:#2d1f0e;
  --cream:#fdf0e0;
  --parch:#f5deb3;
  --muted:#a08060;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{background:var(--smoke);color:var(--cream);font-family:'DM Sans',sans-serif;overflow-x:hidden}
img{max-width:100%;display:block}
a{text-decoration:none;color:inherit}

/* FIRE TEXTURE BG */
.fire-bg{
  position:fixed;inset:0;pointer-events:none;z-index:0;
  background:radial-gradient(ellipse 80% 60% at 50% 100%,rgba(232,93,4,.08) 0%,transparent 70%);
}

/* NAV */
nav{
  position:fixed;top:0;left:0;right:0;z-index:100;
  background:rgba(26,16,8,.95);backdrop-filter:blur(20px);
  border-bottom:1px solid rgba(232,93,4,.2);
  padding:0 40px;height:68px;
  display:flex;align-items:center;justify-content:space-between;
}
.logo{
  display:flex;align-items:center;gap:12px;
}
.logo-icon{font-size:28px;line-height:1}
.logo-text{
  font-family:'Abril Fatface',serif;font-size:22px;color:var(--fire);letter-spacing:.5px;
}
.logo-sub{font-size:10px;letter-spacing:3px;text-transform:uppercase;color:var(--muted)}
.nav-links{display:flex;gap:28px;align-items:center}
.nav-links a{
  font-size:13px;font-weight:500;letter-spacing:.5px;
  color:rgba(253,240,224,.6);transition:.3s;
}
.nav-links a:hover{color:var(--fire)}
.nav-cta{
  background:var(--fire);color:#fff;padding:10px 24px;
  font-size:13px;font-weight:600;letter-spacing:.5px;border-radius:4px;transition:.3s;
}
.nav-cta:hover{background:var(--ember)}

/* HERO */
.hero{
  min-height:100vh;position:relative;overflow:hidden;
  display:flex;align-items:center;margin-top:68px;
}
.hero-bg{
  position:absolute;inset:0;z-index:0;
}
.hero-bg img{
  width:100%;height:100%;object-fit:cover;object-position:center;
  filter:brightness(.35) saturate(1.3);
}
.hero-bg::after{
  content:'';position:absolute;inset:0;
  background:linear-gradient(135deg,rgba(26,16,8,.9) 30%,rgba(26,16,8,.4) 100%);
}
.hero-content{
  position:relative;z-index:2;max-width:1200px;margin:0 auto;
  padding:80px 40px;display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;
  width:100%;
}
.hero-left .eyebrow{
  font-size:11px;letter-spacing:5px;text-transform:uppercase;color:var(--gold);
  margin-bottom:20px;display:flex;align-items:center;gap:12px;
}
.hero-left .eyebrow::before{content:'🔥';font-size:16px}
.hero h1{
  font-family:'Abril Fatface',serif;
  font-size:clamp(56px,6vw,100px);line-height:.9;
  color:var(--cream);margin-bottom:16px;
}
.hero h1 span{
  display:block;color:var(--fire);
  text-shadow:0 0 60px rgba(232,93,4,.5);
}
.hero-tagline{
  font-family:'Libre Baskerville',serif;font-style:italic;
  font-size:20px;color:var(--muted);margin-bottom:32px;
}
.hero-desc{
  font-size:15px;line-height:1.8;color:rgba(253,240,224,.65);
  max-width:440px;margin-bottom:40px;
}
.hero-btns{display:flex;gap:16px;flex-wrap:wrap}
.btn-fire{
  background:var(--fire);color:#fff;padding:15px 36px;
  font-size:14px;font-weight:600;letter-spacing:.5px;
  border-radius:4px;transition:.3s;display:inline-flex;align-items:center;gap:10px;
}
.btn-fire:hover{background:var(--ember);transform:translateY(-2px)}
.btn-ghost{
  border:1.5px solid rgba(253,240,224,.2);color:var(--cream);
  padding:15px 36px;font-size:14px;font-weight:500;
  border-radius:4px;transition:.3s;
}
.btn-ghost:hover{border-color:var(--fire);color:var(--fire)}
.hero-flags{display:flex;gap:16px;margin-top:40px}
.flag-badge{
  display:flex;align-items:center;gap:10px;
  background:rgba(232,93,4,.08);border:1px solid rgba(232,93,4,.15);
  padding:10px 18px;border-radius:4px;
}
.flag-badge span{font-size:12px;color:rgba(253,240,224,.7)}
.hero-right{
  display:flex;flex-direction:column;gap:16px;
}
.mini-cards{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.mini-card{
  background:rgba(253,240,224,.04);border:1px solid rgba(232,93,4,.12);
  padding:20px;border-radius:8px;text-align:center;
}
.mini-card .val{
  font-family:'Abril Fatface',serif;font-size:36px;color:var(--fire);line-height:1;
}
.mini-card .lbl{font-size:11px;color:var(--muted);letter-spacing:1px;margin-top:4px}

/* FLAME DIVIDER */
.flame-div{
  text-align:center;padding:32px 0;background:var(--ash);font-size:32px;
  position:relative;z-index:1;
  letter-spacing:16px;
}

/* MENU SECTION */
.menu-section{background:var(--ash);padding:80px 0;position:relative;z-index:1}
.container{max-width:1200px;margin:0 auto;padding:0 40px}
.section-eyebrow{
  font-size:11px;letter-spacing:5px;text-transform:uppercase;color:var(--gold);
  margin-bottom:8px;display:flex;align-items:center;gap:12px;
}
.section-eyebrow::before{content:'';width:32px;height:1px;background:var(--gold)}
.section-title{
  font-family:'Abril Fatface',serif;font-size:clamp(40px,4vw,64px);
  color:var(--cream);margin-bottom:8px;line-height:1;
}
.section-title em{color:var(--fire);font-style:normal}
.section-sub{font-size:15px;color:var(--muted);line-height:1.6;margin-bottom:48px;max-width:500px}

/* TABS */
.menu-tabs{display:flex;gap:4px;margin-bottom:40px;flex-wrap:wrap}
.tab-btn{
  padding:10px 24px;font-size:13px;font-weight:500;
  background:rgba(253,240,224,.04);border:1px solid rgba(232,93,4,.1);
  color:rgba(253,240,224,.5);cursor:pointer;transition:.3s;border-radius:4px;
}
.tab-btn.active,.tab-btn:hover{background:var(--fire);border-color:var(--fire);color:#fff}

.menu-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.menu-card{
  background:rgba(253,240,224,.03);border:1px solid rgba(232,93,4,.08);
  border-radius:8px;overflow:hidden;transition:.4s;
}
.menu-card:hover{border-color:rgba(232,93,4,.25);transform:translateY(-4px);background:rgba(253,240,224,.05)}
.menu-card-img{
  height:180px;overflow:hidden;position:relative;
}
.menu-card-img img{width:100%;height:100%;object-fit:cover;transition:.5s}
.menu-card:hover .menu-card-img img{transform:scale(1.08)}
.menu-card-flag{
  position:absolute;top:12px;left:12px;
  background:rgba(26,16,8,.8);backdrop-filter:blur(8px);
  padding:4px 10px;border-radius:20px;font-size:12px;
}
.menu-card-body{padding:20px}
.menu-name{
  font-family:'Abril Fatface',serif;font-size:20px;color:var(--cream);margin-bottom:6px;
}
.menu-desc{font-size:13px;color:var(--muted);line-height:1.6;margin-bottom:12px}
.menu-price{font-family:'Abril Fatface',serif;font-size:24px;color:var(--gold)}
.menu-price span{font-size:12px;font-family:'DM Sans',sans-serif;color:var(--muted)}

/* ABOUT */
.about-section{background:var(--smoke);padding:80px 0;position:relative;z-index:1}
.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.about-imgs{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.about-imgs img{width:100%;height:280px;object-fit:cover;border-radius:4px}
.about-imgs img:first-child{height:380px;grid-column:1/-1}
.about-text .section-eyebrow{margin-bottom:12px}
.about-text p{font-size:16px;line-height:1.8;color:rgba(253,240,224,.65);margin-bottom:16px}
.about-tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:24px}
.tag{
  padding:6px 16px;background:rgba(232,93,4,.08);border:1px solid rgba(232,93,4,.15);
  border-radius:20px;font-size:12px;color:var(--fire);font-weight:500;
}

/* GALLERY */
.gallery-section{background:var(--ash);padding:80px 0;position:relative;z-index:1}
.gallery-grid{
  display:grid;
  grid-template-columns:1.5fr 1fr 1fr;
  grid-template-rows:280px 280px;
  gap:6px;
}
.gallery-item{overflow:hidden;position:relative;border-radius:4px;cursor:pointer}
.gallery-item img{width:100%;height:100%;object-fit:cover;transition:.6s}
.gallery-item:hover img{transform:scale(1.08)}
.gallery-item.big{grid-row:1/3}
.gallery-item::after{
  content:'';position:absolute;inset:0;
  background:linear-gradient(to top,rgba(26,16,8,.7) 0%,transparent 50%);
}
.gallery-item-label{
  position:absolute;bottom:16px;left:16px;z-index:2;
  font-size:12px;color:var(--cream);letter-spacing:1px;text-transform:uppercase;
}

/* LOCATION */
.location-section{background:var(--smoke);padding:80px 0;position:relative;z-index:1}
.location-grid{display:grid;grid-template-columns:1fr 1fr;gap:0}
.location-info{background:var(--ash);padding:60px 48px}
.location-map{min-height:400px;overflow:hidden}
.location-map iframe{width:100%;height:100%;border:none;min-height:400px;filter:sepia(40%) saturate(.8) brightness(.9)}
.info-item{
  display:flex;gap:20px;align-items:flex-start;
  padding:20px 0;border-bottom:1px solid rgba(232,93,4,.08);
}
.info-item:last-of-type{border:none}
.info-icon{
  width:44px;height:44px;background:rgba(232,93,4,.1);border:1px solid rgba(232,93,4,.2);
  display:flex;align-items:center;justify-content:center;color:var(--fire);font-size:16px;flex-shrink:0;
  border-radius:4px;
}
.info-label{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--gold);margin-bottom:4px}
.info-val{font-size:15px;color:rgba(253,240,224,.7);line-height:1.6}

/* CTA FIRE BANNER */
.cta-fire{
  background:linear-gradient(135deg,var(--ember) 0%,var(--fire) 50%,var(--gold) 100%);
  padding:80px 40px;text-align:center;position:relative;z-index:1;overflow:hidden;
}
.cta-fire::before{content:'🔥';position:absolute;font-size:300px;opacity:.05;right:-60px;bottom:-100px}
.cta-fire h2{
  font-family:'Abril Fatface',serif;font-size:clamp(40px,5vw,72px);
  color:#fff;margin-bottom:12px;
}
.cta-fire p{font-size:18px;color:rgba(255,255,255,.85);margin-bottom:36px}
.btn-dark{
  background:var(--smoke);color:var(--cream);padding:16px 40px;
  font-size:15px;font-weight:600;border-radius:4px;
  display:inline-flex;align-items:center;gap:12px;transition:.3s;
}
.btn-dark:hover{background:#000;transform:translateY(-2px)}

/* FOOTER */
footer{
  background:var(--smoke);border-top:1px solid rgba(232,93,4,.1);
  padding:60px 40px 40px;position:relative;z-index:1;
}
.footer-inner{
  max-width:1200px;margin:0 auto;
  display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:48px;
}
.footer-brand-name{font-family:'Abril Fatface',serif;font-size:28px;color:var(--fire);margin-bottom:8px}
.footer-brand-desc{font-size:13px;color:var(--muted);line-height:1.7}
.footer-col h4{font-size:11px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);margin-bottom:16px}
.footer-col a{display:block;font-size:14px;color:var(--muted);margin-bottom:8px;transition:.3s}
.footer-col a:hover{color:var(--fire)}
.footer-bottom{
  max-width:1200px;margin:40px auto 0;padding-top:24px;
  border-top:1px solid rgba(232,93,4,.08);
  display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;
}
.footer-bottom p{font-size:12px;color:rgba(253,240,224,.25)}

/* WA */
.wa-float{
  position:fixed;bottom:24px;right:24px;z-index:150;
  width:56px;height:56px;background:#25D366;border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:26px;color:#fff;box-shadow:0 4px 20px rgba(37,211,102,.4);transition:.3s;
}
.wa-float:hover{transform:scale(1.1)}

/* FADE */
.fade-up{opacity:0;transform:translateY(30px);transition:.7s cubic-bezier(.4,0,.2,1)}
.fade-up.vis{opacity:1;transform:translateY(0)}

/* HIDDEN TABS */
.menu-tab-content{display:none}
.menu-tab-content.active{display:grid}

@media(max-width:900px){
  .hero-content{grid-template-columns:1fr;gap:40px}
  .mini-cards{grid-template-columns:repeat(4,1fr)}
  .menu-grid{grid-template-columns:1fr 1fr}
  .about-grid{grid-template-columns:1fr}
  .gallery-grid{grid-template-columns:1fr 1fr;grid-template-rows:auto}
  .gallery-item.big{grid-row:auto}
  .location-grid{grid-template-columns:1fr}
  .footer-inner{grid-template-columns:1fr 1fr}
  nav{padding:0 20px}
  .nav-links{display:none}
}
@media(max-width:600px){
  .menu-grid{grid-template-columns:1fr}
  .mini-cards{grid-template-columns:1fr 1fr}
  .container{padding:0 20px}
}
